#!/usr/bin/env node
"use strict";

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const modulesPath = path.join(root, "game/modules.json");
const bundlePath = path.join(root, "game/bundle.js");
const mapPath = path.join(root, "game/bundle.js.map");
const checkOnly = process.argv.includes("--check");

const base64 =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function vlq(value) {
    let result = "";
    let n = value < 0 ? ((-value) << 1) | 1 : value << 1;
    do {
        let digit = n & 31;
        n >>>= 5;
        if (n > 0) digit |= 32;
        result += base64[digit];
    } while (n > 0);
    return result;
}

function readJSON(file) {
    return JSON.parse(fs.readFileSync(file, "utf8"));
}

function cleanSource(file) {
    return fs
        .readFileSync(file, "utf8")
        .replace(/\r\n/g, "\n")
        .replace(/\n?\/\/# sourceMappingURL=.*$/g, "")
        .replace(/\s+$/, "");
}

const modules = readJSON(modulesPath);
if (!Array.isArray(modules) || modules.length === 0)
    throw new Error("game/modules.json must be a non-empty array");

const seen = new Set();
const sources = [];
for (const entry of modules) {
    if (!entry || typeof entry.id !== "string" || typeof entry.file !== "string")
        throw new Error("Invalid module entry in game/modules.json");
    if (seen.has(entry.id)) throw new Error("Duplicate module id: " + entry.id);
    seen.add(entry.id);
    const file = path.join(root, entry.file);
    if (!fs.existsSync(file)) throw new Error("Missing module file: " + entry.file);
    sources.push({
        id: entry.id,
        mapSource: path.posix.join("modules", path.basename(entry.file)),
        content: cleanSource(file),
    });
}
sources.push({
    id: "prerequisite",
    mapSource: "prerequisite.js",
    content: cleanSource(path.join(root, "game/prerequisite.js")),
});

const generated = [];
const mappings = [];
const mapSources = [];
const sourcesContent = [];
let previousSource = 0;
let previousOriginalLine = 0;

function pushLine(line) {
    generated.push(line);
    mappings.push("");
}

pushLine("// Generated by tools/assemble-game.cjs. Do not edit directly.");
pushLine("// Edit game/modules/*.js or game/source/*.ts instead.");
pushLine("System.register([], function (_export, _context) {");
pushLine("    return {");
pushLine("        execute: function () {");

sources.forEach((source, sourceIndex) => {
    mapSources.push(source.mapSource);
    sourcesContent.push(source.content);
    const lines = source.content.split("\n");
    lines.forEach((line, originalLine) => {
        generated.push("        " + line);
        const segment =
            vlq(line.length ? 8 : 0) +
            vlq(sourceIndex - previousSource) +
            vlq(originalLine - previousOriginalLine) +
            vlq(0);
        mappings.push(segment);
        previousSource = sourceIndex;
        previousOriginalLine = originalLine;
    });
    if (sourceIndex < sources.length - 1) {
        generated.push("");
        mappings.push("");
    }
});

pushLine("        },");
pushLine("    };");
pushLine("});");
pushLine("//# sourceMappingURL=bundle.js.map");

const bundle = generated.join("\n") + "\n";
const map = {
    version: 3,
    file: "bundle.js",
    sources: mapSources,
    sourcesContent,
    names: [],
    mappings: mappings.join(";"),
};
const mapText = JSON.stringify(map);

if (checkOnly) {
    if (!fs.existsSync(bundlePath) || !fs.existsSync(mapPath)) {
        console.error("bundle or source map is missing");
        process.exit(1);
    }
    const currentBundle = fs.readFileSync(bundlePath, "utf8");
    const currentMap = fs.readFileSync(mapPath, "utf8");
    if (currentBundle !== bundle) {
        console.error("game/bundle.js is out of date; run node tools/assemble-game.cjs");
        process.exit(1);
    }
    if (currentMap !== mapText) {
        console.error("game/bundle.js.map is out of date; run node tools/assemble-game.cjs");
        process.exit(1);
    }
    console.log(
        `bundle is up to date: ${sources.length} sources, ${bundle.length} bytes`,
    );
    process.exit(0);
}

fs.writeFileSync(bundlePath, bundle);
fs.writeFileSync(mapPath, mapText);
console.log(
    `wrote game/bundle.js (${bundle.length} bytes) and game/bundle.js.map (${mapText.length} bytes) from ${sources.length} sources`,
);
